contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two amounts: depositAmount to add, and withdrawFlag to decide whether to call withdraw.
    // The function is payable to allow forwarding Ether for deposit.
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // record before-values
        uint beforeReported = c.getBalance(address(this));
        uint beforeContractEth = address(c).balance;

        // perform deposit: call addToBalance forwarding depositAmount wei
        bool depositReverted;
        if (depositAmount == 0) {
            // calling with 0 value is allowed; still call normally
            try c.addToBalance{value: 0}() {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        } else {
            try c.addToBalance{value: depositAmount}() {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        }

        // read after-values
        uint afterReported = c.getBalance(address(this));
        uint afterContractEth = address(c).balance;

        // Optionally attempt withdraw and observe whether it reverts
        bool withdrawReverted = false;
        if (doWithdraw) {
            try c.withdrawBalance() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        }

        uint finalReported = c.getBalance(address(this));
        uint finalContractEth = address(c).balance;

        // General invariant to assert:
        // 1) If deposit did not revert, then afterReported == beforeReported + depositAmount
        //    and afterContractEth == beforeContractEth + depositAmount.
        // 2) If deposit reverted, no changes occurred for these observables.
        // 3) If withdraw was attempted and did not revert, then finalReported == 0 and
        //    finalContractEth + (afterContractEth - finalContractEth) == afterContractEth
        //    i.e., the contract's balance decreased by the amount equal to the reported balance before withdraw.
        // We encode these as a single assert expression.

        bool depositBehavior;
        if (!depositReverted) {
            depositBehavior = (afterReported == beforeReported + depositAmount) && (afterContractEth == beforeContractEth + depositAmount);
        } else {
            depositBehavior = (afterReported == beforeReported) && (afterContractEth == beforeContractEth);
        }

        bool withdrawBehavior;
        if (doWithdraw) {
            if (!withdrawReverted) {
                // If withdraw succeeded, recorded balance must be zero and contract's balance must have decreased by the amount equal
                // to the reported balance just before withdraw (which is afterReported).
                uint decreased = afterContractEth - finalContractEth;
                withdrawBehavior = (finalReported == 0) && (decreased == afterReported);
            } else {
                // If withdraw reverted, state should be unchanged by the attempted withdraw
                withdrawBehavior = (finalReported == afterReported) && (finalContractEth == afterContractEth);
            }
        } else {
            // no withdraw attempted, final equals after
            withdrawBehavior = (finalReported == afterReported) && (finalContractEth == afterContractEth);
        }

        assert(depositBehavior && withdrawBehavior);
    }

    // Allow receiving Ether so this contract can forward deposits
    receive() external payable {}
}

