        if (doWithdraw) {
            try c.withdrawBalance() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            withdrawReverted = true; // treat as not executed => "as if reverted" for our assertion path
        }

        // observe final values
        uint finalReported = c.getBalance(address(this));
        uint finalContractEth = address(c).balance;

