        //    the contract's ETH decreased by exactly the reported balance just before withdraw (which is afterReported):
        //    (afterContractEth - finalContractEth) == afterReported.
        //    If withdraw reverted or was not attempted then finalReported == afterReported and finalContractEth == afterContractEth.

        bool depositBehavior;
        if (!depositReverted) {
            depositBehavior = (afterReported == beforeReported + depositAmount) && (afterContractEth == beforeContractEth + depositAmount);
        } else {
            depositBehavior = (afterReported == beforeReported) && (afterContractEth == beforeContractEth);
        }

        bool withdrawBehavior;
