                // withdraw succeeded
                // afterReported is the recorded balance just before withdraw
                // finalReported must be zero and the contract balance must decrease by exactly afterReported
                // Use subtraction on afterContractEth which is known to be >= finalContractEth if withdraw sent funds out; safe because types are unsigned and we don't underflow in spec
                withdrawBehavior = (finalReported == 0) && ((afterContractEth - finalContractEth) == afterReported);
