    function run(uint256 amount) public payable {
        // ensure this test contract can forward the requested amount
        require(address(this).balance >= amount);

        // observe before-values
        uint256 beforeRecorded = c.getBalance(address(this));
        uint256 beforeContractEth = address(c).balance;

        // call addToBalance and record whether it reverted
        bool reverted;
        try c.addToBalance{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 afterRecorded = c.getBalance(address(this));
        uint256 afterContractEth = address(c).balance;

        // If the call succeeded then: (1) c's Ether balance increased exactly by amount,
        // and (2) the recorded user balance for this test did not increase by more than amount.
        // If it reverted, no guarantees.
        assert(reverted || (afterContractEth == beforeContractEth + amount && afterRecorded <= beforeRecorded + amount));
    }

    receive() external payable {}
}
